pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a VAULT mock (simplified: we just need totalWeight() to work)
        // We deploy a minimal contract that returns a fixed totalWeight
        // But the problem only cares about VADER after cancelProposal
        // Minimal: create a vault that returns nonzero totalWeight
        vm.etch(address(0x1), type(MockVault).runtimeCode);
        IMockVault mockVault = IMockVault(address(0x1));
        mockVault.setTotalWeight(100 ether);

        // Deploy a mock VADER (we only need setRewardAddress to exist, but not called)
        vm.etch(address(0x2), type(MockVader).runtimeCode);

        // init the contract with VADER = 0x2, USDV = 0x3, VAULT = 0x1
        vm.startPrank(address(0x100));
        c.init(address(0x2), address(0x3), address(0x1));
        vm.stopPrank();

        // Create a GRANT proposal (type GRANT) with recipient and amount
        // Proposal ID 1: GRANT type
        c.newGrantProposal(address(0x200), 1000);

        // Now create an address proposal of type "GRANT" (same type string)
        c.newAddressProposal(address(0x300), "GRANT");

        // Vote on first proposal to get it into finalising state
        // We need to simulate a voter with weight > totalWeight/6 to meet minority
        // For cancelling, oldProposal must be finalising and newProposal must have minority
        vm.startPrank(address(0x100));
        // First vote on old proposal (ID 1) to make it finalising
        // But voteProposal calls countMemberVotes which calls getMemberWeight
        // We need to set up the mock vault to return a weight
        mockVault.setMemberWeight(address(0x100), 10 ether);
        mockVault.setTotalWeight(100 ether);

        // Vote on proposal 1 (GRANT) — this will trigger finalising if hasQuorum and majority
        // hasQuorum: votes > totalWeight/3 = 33.33, not met with 10 votes, so not finalised
        // But we need finalising state — we'll call voteProposal again to increase votes
        c.voteProposal(1);
        vm.stopPrank();

        // Second voter makes total votes 20, still not quorum
        vm.prank(address(0x101));
        mockVault.setMemberWeight(address(0x101), 10 ether);
        c.voteProposal(1);

        // Third voter makes total votes 30, still not quorum (33.33 needed)
        vm.prank(address(0x102));
        mockVault.setMemberWeight(address(0x102), 10 ether);
        c.voteProposal(1);

        // Fourth voter makes total votes 40, now quorum (40 > 33) and majority (40 > 50? no, 50 needed)
        // But for GRANT type, finalising happens with ANY quorum (see voteProposal logic)
        vm.prank(address(0x103));
        mockVault.setMemberWeight(address(0x103), 10 ether);
        c.voteProposal(1);

        // Now proposal 1 should be finalising (mapPID_finalising[1] = true)
        // Now we need proposal 2 to have minority (> totalWeight/6 = 16.66)
        // Cast 20 votes on proposal 2
        vm.prank(address(0x100));
        // We already set mockVault member weight for 0x100 to 10
        c.voteProposal(2);
        vm.prank(address(0x101));
        c.voteProposal(2);
        // Now mapPID_votes[2] = 20, which > 16.66 so hasMinority true

        // Now call cancelProposal(1, 2)
        vm.prank(address(0x100));
        c.cancelProposal(1, 2);

        // After cancelProposal, check VADER
        // Reference: VADER = 0x2 (set in init)
        // Buggy: VADER = address(0) (not set in init)
        assertTrue(c.VADER() == address(0x2), "VADER should be set");
    }
}

interface IMockVault {
    function totalWeight() external view returns (uint);
    function setTotalWeight(uint) external;
    function setMemberWeight(address, uint) external;
    function getMemberWeight(address) external view returns (uint);
}

contract MockVault {
    uint public totalWeight;
    mapping(address => uint) public memberWeight;
    function setTotalWeight(uint w) external { totalWeight = w; }
    function setMemberWeight(address m, uint w) external { memberWeight[m] = w; }
    function getMemberWeight(address m) external view returns (uint) { return memberWeight[m]; }
}

