pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy needed external contracts (mocks for iVADER and iVAULT)
        VADERMock vader = new VADERMock();
        VAULTMock vault = new VAULTMock();
        c.init(address(vader), address(0x1), address(vault));

        // Create proposal 1 (GRANT, finalising via vote and then finaliseProposal to set timeStart)
        vm.prank(address(0x100));
        c.newGrantProposal(address(0x200), 100);
        // Vote for proposal 1 to make it finalising (requires quorum but less than majority)
        // Need to set vault.totalWeight() = 12 so quorum = 4, majority = 6
        vault.setTotalWeight(12);
        vault.setMemberWeight(address(0x100), 4);
        vm.prank(address(0x100));
        c.voteProposal(1);
        // Now proposal 1 is finalising, timeStart set to block.timestamp

        // Create proposal 2 (GRANT)
        vm.prank(address(0x101));
        c.newGrantProposal(address(0x300), 200);
        // Vote for proposal 2 to give it minority votes (needs < totalWeight/6 = 2 votes)
        vault.setMemberWeight(address(0x101), 1);
        vm.prank(address(0x101));
        c.voteProposal(2);

        // Wait past coolOffPeriod for proposal 1
        vm.warp(block.timestamp + 10);

        // Now call cancelProposal(1,2)
        vm.prank(address(0x100));
        c.cancelProposal(1, 2);

        // Assert: mapPID_votes[1] should be 0 in reference but 4 in buggy
        assertTrue(c.mapPID_votes(1) == 0, "mapPID_votes[1] should be 0 after cancelProposal");
    }
}

