contract VAULTMock {
    uint public totalWeightValue;
    mapping(address => uint) public memberWeight;

    function setTotalWeight(uint w) external { totalWeightValue = w; }
    function setMemberWeight(address m, uint w) external { memberWeight[m] = w; }
    function totalWeight() external view returns (uint) { return totalWeightValue; }
    function getMemberWeight(address m) external view returns (uint) { return memberWeight[m]; }
    function grant(address, uint) external {}
}
